// Assemble the payload once, here, in the shape the contract requires
// (ai-standards/references/notification-taxonomy.md — "The message contract").
// Downstream branches only reshape it to each platform's wire format.
//
// BLUF: title states the OUTCOME, then the action line, then the one number,
// then supporting detail, then provenance small and last. The reader is scanning
// a phone and deciding in ~2s whether this needs them.
const i = $input.first().json || {};
const NL = String.fromCharCode(10);

const severity = (i.severity || 'info').toLowerCase();
const title = (i.title || 'Notification').trim();
const detail = (i.message || '').trim();
const source = i.source || 'n8n';
const metric = (i.metric || '').trim();

// Severity is DEFINED, not felt — same three words everywhere, or the colours
// stop meaning anything. Each maps to exactly one reader obligation.
const OBLIGATION = { error: 'Act now', warn: 'Decide this week', info: 'No action' };
// A caller may state the action explicitly ("Act by 2026-08-24"); otherwise it is
// derived, so a lane that forgets still emits a contract-shaped message rather
// than leaving the reader to infer urgency from tone.
const action = (i.action || '').trim() || OBLIGATION[severity] || 'No action';
const emoji = severity === 'error' ? '\uD83D\uDD34'
            : severity === 'warn'  ? '\uD83D\uDFE1'
            : '\uD83D\uDFE2';

// Detail lives behind a link — but assume the link is never opened. Most of our
// detail surfaces are localhost-bound and unreachable from the phone the alert
// was read on, so the MESSAGE must carry the decision and the link only carries
// the evidence.
const base = ($env.N8N_BASE_URL || 'http://localhost:5678').replace(/\/+$/, '');
const runUrl = i.runUrl || (base + '/home/executions');
const runLabel = i.runUrl ? 'View run' : 'Open executions';

// Slack hard limits: header plain_text 150, section text 3000. Truncate loudly
// rather than letting Slack reject the whole message.
const clip = (s, n) => (s.length > n ? s.slice(0, n - 20) + NL + '… (truncated)' : s);

const blocks = [
  { type: 'header',
    text: { type: 'plain_text', text: clip(`${emoji} ${title}`, 150), emoji: true } },
  { type: 'section',
    text: { type: 'mrkdwn', text: `*${action}*` } },
];

if (metric) {
  blocks.push({ type: 'section', fields: [
    { type: 'mrkdwn', text: `*Key figure*${NL}${clip(metric, 600)}` },
    { type: 'mrkdwn', text: `*Severity*${NL}\`${severity}\`` },
  ] });
}
if (detail) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: clip(detail, 2800) } });
}
// Provenance last and small. Naming the lane is what lets a noisy alert be
// traced to a workflow and fixed rather than muted.
blocks.push({ type: 'context', elements: [
  { type: 'mrkdwn', text: `lane: \`${source}\`  ·  <${runUrl}|${runLabel}>` } ]});

// Fallback text: what a phone notification shows, and what Teams/webhook use.
// It carries the decision on its own — title plus action, nothing else.
const text = `${emoji} ${title} — ${action}`;
// Long form for channels without Block Kit.
const longText = [`${emoji} *${title}* (${severity})`, `*${action}*`,
                  metric, detail, `_lane: ${source} · ${runUrl}_`]
                 .filter(Boolean).join(NL);

return [{ json: { severity, title, message: detail, source, action, metric,
                  runUrl, text, longText, blocks } }];
